import os, json, time, numpy as np

SHARED = 'storage/shared/appxE_contribs'
OUT_DIR = 'storage/noesis/nmap'
OUT_MAIN = os.path.join(OUT_DIR, 'research', 'appendix_E_kkt_meta_v2_1.json')
NOESIS_COMPARE = os.path.join(OUT_DIR, 'results', 'noesis_kkt_slack_compare_v2_1.json')

def _ts():
    return time.strftime('%Y-%m-%dT%H:%M:%SZ', time.gmtime())

def _ensure():
    os.makedirs(os.path.join(OUT_DIR, 'research'), exist_ok=True)
    os.makedirs(os.path.join(OUT_DIR, 'freezes'), exist_ok=True)

def _class_key(fn):
    s = fn
    for tok in ['_kkt_top_k_1e_9.json', '_kkt_top_k_1e_8.json', '.json']:
        s = s.replace(tok, '')
    return s

def _scan_kkt():
    try:
        files = [f for f in os.listdir(SHARED) if f.endswith('.json')]
    except Exception:
        files = []
    classes = {}
    for fn in files:
        if '_kkt_top_k_1e_9.json' in fn:
            key = _class_key(fn)
            rec = classes.setdefault(key, {'has_1e9': False, 'has_1e8': False})
            rec['has_1e9'] = True
        elif '_kkt_top_k_1e_8.json' in fn:
            key = _class_key(fn)
            rec = classes.setdefault(key, {'has_1e9': False, 'has_1e8': False})
            rec['has_1e8'] = True
    # build coverage
    total = len(classes)
    both = sum(1 for v in classes.values() if v['has_1e9'] and v['has_1e8'])
    only_1e9 = sum(1 for v in classes.values() if v['has_1e9'] and not v['has_1e8'])
    only_1e8 = sum(1 for v in classes.values() if v['has_1e8'] and not v['has_1e9'])
    none = 0  # not listed since we only index classes that appear with at least one KKT file
    per_class = [{'class': k, **v} for k,v in sorted(classes.items())]
    return {
        'class_count_with_any_kkt': total,
        'class_count_with_both': both,
        'class_count_only_1e9': only_1e9,
        'class_count_only_1e8': only_1e8,
        'class_count_none': none,
        'per_class': per_class
    }

def _read_noesis_compare():
    try:
        with open(NOESIS_COMPARE, 'r') as f:
            data = json.load(f)
        return {
            'eval_ref': data.get('eval_ref'),
            'by_tol': data.get('by_tol', {})
        }
    except Exception:
        return None

def _write(payload):
    _ensure()
    with open(OUT_MAIN, 'w') as f:
        json.dump(payload, f, indent=2)
    stamp = time.strftime('%Y-%m-%dT%H-%M-%SZ', time.gmtime())
    freeze = os.path.join(OUT_DIR, 'freezes', f'appendix_E_kkt_meta_v2_1_{stamp}.json')
    with open(freeze, 'w') as f:
        json.dump(payload, f, indent=2)
    return freeze

def construct_packing():
    meta = _scan_kkt()
    snap = _read_noesis_compare()
    payload = {
        'generated_at': _ts(),
        'schema': 'v2.1',
        'source_dir': SHARED,
        'kkt_presence': meta,
        'noesis_snapshot_kkt_slack': snap
    }
    try:
        _write(payload)
    except Exception:
        pass
    # return baseline with tiny shrink
    try:
        c = np.loadtxt('storage/noesis/latest_centers.txt', dtype=float).reshape(26,2)
        r = np.loadtxt('storage/noesis/latest_radii.txt', dtype=float).reshape(26,)
    except Exception:
        # conservative fallback grid
        centers = []
        rad = 0.08
        for i in range(5):
            for j in range(6):
                if len(centers) < 26:
                    centers.append([0.1 + 0.2*i, 0.1 + 0.15*j])
        c = np.array(centers, float); r = np.full(26, rad, float)
    r = np.maximum(r - 1e-9, 1e-12)
    return c.astype(float), r.astype(float)
